/** Only invitations deliberately generated by this device are retained offline.
 * The token acts as a bearer invitation. Never cache it in the shared PWA
 * service-worker cache, and erase it when the account signs out.
 */
export const OWN_GROUP_INVITES_KEY='submundo-own-group-invites-v1';
const EXPIRES_AFTER=30*24*60*60*1000;
const MAX_CACHED_GROUPS=40;
export type CachedGroupInvite={groupId:string;name:string;token:string;createdAt:number};

export function getCachedGroupInvites(now=Date.now()):CachedGroupInvite[]{
 try{
  const parsed:unknown=JSON.parse(localStorage.getItem(OWN_GROUP_INVITES_KEY)||'[]');
  if(!Array.isArray(parsed))return [];
  return parsed.filter((entry):entry is CachedGroupInvite=>
   !!entry&&typeof entry==='object'&&
   typeof entry.groupId==='string'&&entry.groupId.length>0&&entry.groupId.length<=128&&
   typeof entry.name==='string'&&entry.name.length>0&&entry.name.length<=100&&
   typeof entry.token==='string'&&/^[a-f0-9]{64}$/.test(entry.token)&&
   typeof entry.createdAt==='number'&&Number.isFinite(entry.createdAt)&&
   entry.createdAt<=now&&now-entry.createdAt<EXPIRES_AFTER
  ).slice(0,MAX_CACHED_GROUPS);
 }catch{return [];}
}
export function cacheGroupInvite(groupId:string,name:string,token:string,now=Date.now()):void{
 if(!groupId||groupId.length>128||!name||!/^[a-f0-9]{64}$/.test(token))return;
 try{
  const existing=getCachedGroupInvites(now).filter(item=>item.groupId!==groupId);
  localStorage.setItem(OWN_GROUP_INVITES_KEY,JSON.stringify([{groupId,name:name.slice(0,100),token,createdAt:now},...existing].slice(0,MAX_CACHED_GROUPS)));
 }catch{/* Private browsing or storage disabled: QR still works while modal is open. */}
}
export function findCachedGroupInvite(groupId:string):CachedGroupInvite|undefined{
 return getCachedGroupInvites().find(item=>item.groupId===groupId);
}
export function removeCachedGroupInvite(groupId:string):void{
 try{localStorage.setItem(OWN_GROUP_INVITES_KEY,JSON.stringify(getCachedGroupInvites().filter(x=>x.groupId!==groupId)));}catch{}
}
export function clearCachedGroupInvites():void{
 try{localStorage.removeItem(OWN_GROUP_INVITES_KEY);}catch{}
}
export function groupInviteUrl(token:string):string{
 return window.location.origin+'/groups?group_invite='+encodeURIComponent(token);
}
